import {test} from 'node:test';import assert from 'node:assert/strict';import {mkdtempSync,mkdirSync,writeFileSync,readFileSync,rmSync,symlinkSync} from 'node:fs';import {tmpdir} from 'node:os';import {join,resolve,basename} from 'node:path';import {fileURLToPath} from 'node:url';import {createHash} from 'node:crypto';import {applyPatch} from './apply-pixi-reset-patch.mjs';
const metadata=JSON.parse(readFileSync(new URL('./pixi-reset-patch.json',import.meta.url),'utf8'));
const hash=b=>createHash('sha256').update(b).digest('hex');
// Installed exact admitted files supply fixture donors; no checked-in vendor copies.
const appRoot=resolve(fileURLToPath(new URL('..',import.meta.url)));
function donorOriginal(f){
 const raw=readFileSync(join(appRoot,'node_modules/pixi.js',f.relativePath));const digest=hash(raw);
 if(digest===f.originalSha256)return raw;
 assert.equal(digest,f.patchedSha256,'installed donor must be exactly admitted');
 let text=raw.toString('utf8');
 // Reverse ONLY exact edits and removed source-map comment recorded in metadata.
 for(const edit of [...f.edits].reverse()){
  if(edit.after===''){assert.equal(edit.before,'//# sourceMappingURL='+basename(f.relativePath)+'.map\n');text+=edit.before;}
  else{assert.equal(text.split(edit.after).length,2,'unique patched reset inverse');text=text.replace(edit.after,edit.before);}
 }
 const original=Buffer.from(text);assert.equal(hash(original),f.originalSha256,'inverse original full checksum');return original;
}
function donorPatched(f){let text=donorOriginal(f).toString('utf8');for(const edit of f.edits){assert.equal(text.split(edit.before).length,2);text=text.replace(edit.before,edit.after);}const patched=Buffer.from(text);assert.equal(hash(patched),f.patchedSha256);return patched;}
function fixture(){const root=mkdtempSync(join(tmpdir(),'pixi-reset-install-contract-')),dep=join(root,'node_modules/pixi.js');mkdirSync(dep,{recursive:true});writeFileSync(join(root,'package.json'),JSON.stringify({dependencies:{'pixi.js':metadata.version}}));writeFileSync(join(root,'package-lock.json'),JSON.stringify({packages:{'':{dependencies:{'pixi.js':metadata.version}},'node_modules/pixi.js':{version:metadata.version,resolved:metadata.resolved,integrity:metadata.integrity}}}));writeFileSync(join(dep,'package.json'),JSON.stringify({version:metadata.version}));for(const f of metadata.files){const target=join(dep,f.relativePath);mkdirSync(join(target,'..'),{recursive:true});writeFileSync(target,donorOriginal(f));}return {root,dep,clean:()=>rmSync(root,{recursive:true,force:true})};}
test('exact fresh install patches all metadata files once then idempotently verifies',()=>{const f=fixture();try{assert.deepEqual(applyPatch(f.root),{version:'8.21.0',changed:metadata.files.length,verified:metadata.files.length});assert.deepEqual(applyPatch(f.root),{version:'8.21.0',changed:0,verified:metadata.files.length});for(const m of metadata.files){assert.deepEqual(readFileSync(join(f.dep,m.relativePath)),donorPatched(m));}}finally{f.clean();}});
test('unknown installed version and lock integrity fail before mutation',()=>{for(const mode of ['version','integrity']){const f=fixture();try{if(mode==='version')writeFileSync(join(f.dep,'package.json'),'{"version":"8.22.0"}');else{const lock=JSON.parse(readFileSync(join(f.root,'package-lock.json'),'utf8'));lock.packages['node_modules/pixi.js'].integrity='unknown';writeFileSync(join(f.root,'package-lock.json'),JSON.stringify(lock));}const before=metadata.files.map(m=>readFileSync(join(f.dep,m.relativePath)));assert.throws(()=>applyPatch(f.root),/guard failed/);metadata.files.forEach((m,i)=>assert.deepEqual(readFileSync(join(f.dep,m.relativePath)),before[i]));}finally{f.clean();}}});
test('unknown last-file source cannot partially patch any preceding admitted file',()=>{const f=fixture();try{const preceding=metadata.files.slice(0,-1).map(m=>({path:join(f.dep,m.relativePath),original:readFileSync(join(f.dep,m.relativePath))}));writeFileSync(join(f.dep,metadata.files.at(-1).relativePath),'unknown source');assert.throws(()=>applyPatch(f.root),/unknown source hash/);for(const item of preceding)assert.deepEqual(readFileSync(item.path),item.original);}finally{f.clean();}});
test('mixed admitted original/patched state safely converges',()=>{const f=fixture();try{writeFileSync(join(f.dep,metadata.files[0].relativePath),donorPatched(metadata.files[0]));assert.deepEqual(applyPatch(f.root),{version:'8.21.0',changed:metadata.files.length-1,verified:metadata.files.length});}finally{f.clean();}});
test('external shared dependency symlink rejected without writing it',()=>{const f=fixture(),other=fixture();try{rmSync(f.dep,{recursive:true});symlinkSync(other.dep,f.dep);const before=metadata.files.map(m=>readFileSync(join(other.dep,m.relativePath)));assert.throws(()=>applyPatch(f.root),/external shared dependency tree/);metadata.files.forEach((m,i)=>assert.deepEqual(readFileSync(join(other.dep,m.relativePath)),before[i]));}finally{f.clean();other.clean();}});
